WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_ms_org_research'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '调研考察类', 'kp-ms-org-research', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "计划组织：调研考察类"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心要求：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "获取真实、有效的数据。调研对象必须全面，调研方式必须多样。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、万能调研框架"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "调研目的：明确这次调研是为了解决什么问题，不写废话。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "调研对象：采用【利益相关方全覆盖】法。比如调研外卖员交通安全，对象必须包括：外卖员、平台经理、交警、路人。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "调研方式：线上问卷（面广）+ 线下走访/暗访（求真）+ 座谈会（听取意见）+ 查阅文献（找历史数据）。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "调研内容：不仅要问现状、问困难，还要问【对策建议】。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "结果处理：数据脱敏、交叉比对、撰写调研报告，并附上切实可行的整改建议，呈报领导。"}]}]}]}]}$$ AS jsonb), NULL, '调研考察类的核心考点与高分作答技巧。', category_node.id, CAST('["面试", "计划组织", "调研"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_ms_org_research", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
